void LineEdit::_set_text(String p_text, bool p_emit_signal) {
	clear_internal();

	String previous_text = get_text();
	insert_text_at_caret(p_text);

	if (get_text() != previous_text) {
		_create_undo_state();
		if (p_emit_signal) {
			_text_changed();
		}
	}

	queue_redraw();
	caret_column = 0;
	scroll_offset = 0.0;
}

void LineEdit::set_text(String p_text) {
	_set_text(p_text);
}
